edits.before:
this._cancelHandler = event => {
  event.preventDefault()

  if (!this._config.keyboard) {
    this._triggerBackdropTransition()
    return
  }

  this._onCancel()
  this.hide()
}

edits.after:
this._cancelHandler = event => {
  event.preventDefault()
  if (!this._config.keyboard) {
    return
  }
  this._onCancel()
  this.hide()
}
